import { useEffect, useState } from 'react';
import { AlertCircle, Loader2, Printer, X } from 'lucide-react';
import { productionService } from '../api/production.service';
import { ATTESTATION_TYPES } from '../../shared/service-forms';
import type { GeneratedDocument } from '../types/scolarite';
import { formatDateShort, formatDateTime } from '../utils/format';
import { isDemoMode } from '../utils/demo';

interface DocumentPreviewProps {
  productionId: string;
  onClose: () => void;
}

/**
 * Renders the document generated by the server (a frozen data snapshot with
 * its own reference and version) as a printable page. "Imprimer" uses the
 * browser print dialog, which can also save it as PDF.
 */
export function DocumentPreview({ productionId, onClose }: DocumentPreviewProps) {
  const [doc, setDoc] = useState<GeneratedDocument | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    productionService
      .getGeneratedDocument(productionId)
      .then((d) => active && setDoc(d))
      .catch((err) => active && setError(err instanceof Error ? err.message : 'Document indisponible.'));
    return () => {
      active = false;
    };
  }, [productionId]);

  return (
    <div className="fixed inset-0 z-[60] flex items-start justify-center overflow-y-auto bg-ink/55 backdrop-xs p-4" role="dialog" aria-modal="true">
      <div className="w-full max-w-3xl my-6 space-y-3">
        <div className="no-print flex items-center justify-between rounded-xl bg-white px-4 py-2.5">
          <div className="text-sm font-medium text-ink">
            Document généré {doc && <span className="font-mono-ref text-ink ml-1">{doc.documentReference}</span>}
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              disabled={!doc}
              onClick={() => window.print()}
              className="inline-flex items-center gap-1.5 rounded-lg bg-ink px-3 py-1.5 text-xs font-medium text-white hover:bg-black disabled:opacity-50 cursor-pointer"
            >
              <Printer className="h-3.5 w-3.5" />
              Imprimer / PDF
            </button>
            <button type="button" onClick={onClose} className="rounded-lg p-1.5 text-ink/60 hover:bg-panel cursor-pointer" aria-label="Fermer">
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>

        {error && (
          <div className="no-print flex items-center gap-2 rounded-xl bg-rose-50 border border-rose-200 px-4 py-3 text-sm text-rose-800">
            <AlertCircle className="h-4 w-4 shrink-0" />
            {error}
          </div>
        )}
        {!doc && !error && (
          <div className="no-print flex items-center justify-center gap-2 rounded-xl bg-white p-10 text-sm text-ink/70">
            <Loader2 className="h-4 w-4 animate-spin" /> Chargement du document...
          </div>
        )}
        {doc && <DocumentSheet doc={doc} />}
      </div>
    </div>
  );
}

function DocumentSheet({ doc }: { doc: GeneratedDocument }) {
  const fullName = `${doc.student.nom} ${doc.student.prenom}`;
  const year = doc.details.academicYear;

  return (
    <article className="print-area relative overflow-hidden rounded-xl bg-white px-10 py-12 text-ink" style={{ fontFamily: 'Georgia, "Times New Roman", serif' }}>
      {isDemoMode() && (
        <div className="pointer-events-none absolute inset-0 flex items-center justify-center" aria-hidden>
          <span className="rotate-[-28deg] text-7xl font-medium tracking-widest text-rose-500/15">SPÉCIMEN — DÉMO</span>
        </div>
      )}

      <header className="flex items-start justify-between border-b-2 border-ink pb-4">
        <div>
          <div className="text-lg font-medium uppercase tracking-wide text-ink">{doc.institutionName}</div>
          <div className="text-sm text-ink/70">Service de la Scolarité — UniNotes</div>
        </div>
        <div className="text-right text-xs text-ink/70" style={{ fontFamily: 'ui-monospace, monospace' }}>
          <div>N° {doc.documentReference}</div>
          <div>Version {doc.version}</div>
          <div>Transaction {doc.transactionReference}</div>
        </div>
      </header>

      <h1 className="mt-10 text-center text-2xl font-medium uppercase tracking-[0.2em]">{documentHeading(doc)}</h1>

      <section className="mt-10 space-y-4 text-[15px] leading-relaxed">
        {doc.documentType === 'ATTESTATION' && (
          <>
            <p>
              Le Responsable du Service de la Scolarité soussigné atteste que l’étudiant(e) <strong>{fullName}</strong>,
              matricule <strong>{doc.student.matricule}</strong>, {attestationSentence(doc.details.attestationType)}{' '}
              <strong>{doc.student.promotion}</strong> au titre de l’année universitaire <strong>{year}</strong>.
            </p>
            {doc.details.purpose && <p>Motif de la demande : {doc.details.purpose}.</p>}
            <p>La présente attestation est délivrée à l’intéressé(e) pour servir et valoir ce que de droit.</p>
          </>
        )}

        {doc.documentType === 'CERTIFICATION' && (
          <>
            <p>
              Le Service de la Scolarité certifie conforme à l’original présenté par <strong>{fullName}</strong>
              (matricule <strong>{doc.student.matricule}</strong>, {doc.student.promotion}) le document suivant :
            </p>
            <p className="pl-6 italic">« {doc.details.documentToCertify} » — {doc.details.copies} exemplaire(s).</p>
          </>
        )}

        {doc.documentType === 'RELEVE_NOTES' && <TranscriptBody doc={doc} />}

        {!['ATTESTATION', 'CERTIFICATION', 'RELEVE_NOTES'].includes(doc.documentType) && (
          <p>
            Document « {doc.title} » établi au nom de <strong>{fullName}</strong> (matricule {doc.student.matricule},{' '}
            {doc.student.promotion}).
          </p>
        )}
      </section>

      <footer className="mt-16 flex items-end justify-between text-sm">
        <div className="text-xs text-ink/60" style={{ fontFamily: 'ui-monospace, monospace' }}>
          Généré le {formatDateTime(doc.generatedAt)}
        </div>
        <div className="text-center">
          <div>Fait le {formatDateShort(doc.generatedAt)}</div>
          <div className="mt-1 font-medium">Le Responsable de la Scolarité</div>
          <div className="mt-14 text-xs text-ink/60">(Signature et cachet)</div>
        </div>
      </footer>
    </article>
  );
}

function documentHeading(doc: GeneratedDocument): string {
  if (doc.documentType === 'ATTESTATION') {
    return ATTESTATION_TYPES.find((t) => t.value === doc.details.attestationType)?.label ?? 'Attestation';
  }
  return doc.title;
}

function attestationSentence(type: string | undefined): string {
  if (type === 'INSCRIPTION') return 'a procédé à son inscription administrative en';
  if (type === 'REUSSITE') return 'a satisfait aux épreuves de';
  return 'est régulièrement inscrit(e) en';
}

function TranscriptBody({ doc }: { doc: GeneratedDocument }) {
  const totalCredits = doc.grades.reduce((sum, g) => sum + g.credits, 0);
  const average = totalCredits > 0 ? doc.grades.reduce((sum, g) => sum + g.grade * g.credits, 0) / totalCredits : null;

  return (
    <>
      <p>
        Étudiant(e) : <strong>{doc.student.nom} {doc.student.prenom}</strong> — Matricule{' '}
        <strong>{doc.student.matricule}</strong> — {doc.student.promotion}
        <br />
        Année universitaire : <strong>{doc.details.academicYear}</strong> — Semestre(s) : <strong>{doc.details.semester}</strong>
      </p>
      {doc.grades.length === 0 ? (
        <p className="rounded border border-amber-300 bg-amber-50 p-3 text-sm text-amber-900">
          Aucune note enregistrée dans UniNotes pour cet étudiant : le relevé ne peut pas être validé en l’état.
        </p>
      ) : (
        <table className="w-full border-collapse text-sm">
          <thead>
            <tr className="border-y border-slate-400 text-left">
              <th className="py-1.5 pr-2">Sem.</th>
              <th className="py-1.5 pr-2">Code</th>
              <th className="py-1.5 pr-2">Unité d’enseignement</th>
              <th className="py-1.5 pr-2 text-right">Crédits</th>
              <th className="py-1.5 pr-2 text-right">Note /20</th>
              <th className="py-1.5">Résultat</th>
            </tr>
          </thead>
          <tbody>
            {doc.grades.map((g) => (
              <tr key={`${g.semester}-${g.courseCode}`} className="border-b border-ink/10">
                <td className="py-1.5 pr-2">{g.semester}</td>
                <td className="py-1.5 pr-2">{g.courseCode}</td>
                <td className="py-1.5 pr-2">{g.courseName}</td>
                <td className="py-1.5 pr-2 text-right tabular-nums">{g.credits}</td>
                <td className="py-1.5 pr-2 text-right tabular-nums">{g.grade.toFixed(2)}</td>
                <td className="py-1.5">{g.status}</td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr className="border-t border-slate-400 font-medium">
              <td colSpan={3} className="py-1.5">Total / Moyenne pondérée</td>
              <td className="py-1.5 pr-2 text-right tabular-nums">{totalCredits}</td>
              <td className="py-1.5 pr-2 text-right tabular-nums">{average !== null ? average.toFixed(2) : '—'}</td>
              <td />
            </tr>
          </tfoot>
        </table>
      )}
    </>
  );
}
